 "content": "def transform(grid):
    """Fill cells between consecutive markers in each row and column."""
    from collections import Counter

    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    marker = next(v for v, _ in counts.most_common() if v != background)
    fill = 3
    h, w = len(grid), len(grid[0])

    for r in range(h):
        marks = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(marks, marks[1:]):
            for c in range(a + 1, b):
                out[r][c] = fill

    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(marks, marks[1:]):
            for r in range(a + 1, b):
                out[r][c] = fill

    return out


